using System.Text.Json;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// Response: no cardLast4, because the property is declared as Payment
app.MapGet("/orders/{id:int}", (int id) => new Order(id, "Mona",
    OrderStatus.Paid, new CardPayment { Amount = 12.5m, CardLast4 = "4242" }));
// Body with "status": "Paid" gets a 400: enum names aren't read by default
app.MapPost("/orders", (Order order) => TypedResults.Ok(order.Status));
app.Run();

// Own calls skip ASP.NET Core's settings: PascalCase, non-ASCII escaped
static string ToOutbox(Order order) => JsonSerializer.Serialize(order);

public class Payment { public decimal Amount { get; set; } }
public class CardPayment : Payment { public string? CardLast4 { get; set; } }

using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Unicode;

var builder = WebApplication.CreateBuilder(args);
builder.Services.ConfigureHttpJsonOptions(o => // minimal APIs
    o.SerializerOptions.Converters.Add(new JsonStringEnumConverter()));
var app = builder.Build();
// ...the same two endpoints...
app.Run();

// One shared options instance: web naming, Arabic kept readable
static string ToOutbox(Order order) => JsonSerializer.Serialize(order, Json.Web);

[JsonDerivedType(typeof(CardPayment))] // write the runtime type's properties
public class Payment { public decimal Amount { get; set; } }
public class CardPayment : Payment { public string? CardLast4 { get; set; } }
static class Json
{
    static readonly JavaScriptEncoder Arabic =
        JavaScriptEncoder.Create(UnicodeRanges.BasicLatin, UnicodeRanges.Arabic);
    public static readonly JsonSerializerOptions Web =
        new(JsonSerializerDefaults.Web) { Encoder = Arabic };
}
